   917  static readstat_error_t sav_parse_machine_integer_info_record(const void *data, size_t data_len, sav_ctx_t *ctx) {
   918      if (data_len != 32)
   919          return READSTAT_ERROR_PARSE;
   920
   921      const char *src_charset = NULL;
   922      const char *dst_charset = ctx->output_encoding;
   923      sav_machine_integer_info_record_t record;
   924      memcpy(&record, data, data_len);
   925      if (ctx->bswap) {
   926          record.character_code = byteswap4(record.character_code);
   927      }
   928      if (ctx->input_encoding) {
   929          src_charset = ctx->input_encoding;
   930      } else {
   931          int i;
   932          for (i=0; i<sizeof(_charset_table)/sizeof(_charset_table[0]); i++) {
   933              if (record.character_code  == _charset_table[i].code) {
   934                  src_charset = _charset_table[i].name;
   935                  break;
   936              }
   937          }
   938          if (src_charset == NULL) {
   939              if (ctx->handle.error) {
   940                  char error_buf[1024];
   941                  snprintf(error_buf, sizeof(error_buf), "Unsupported character set: %d\n", record.character_code);
   942                  ctx->handle.error(error_buf, ctx->user_ctx);
   943              }
   944              return READSTAT_ERROR_UNSUPPORTED_CHARSET;
   945          }
   946          ctx->input_encoding = src_charset;
   947      }
   948      if (src_charset && dst_charset) {
   949          // You might be tempted to skip the charset conversion when src_charset
   950          // and dst_charset are the same. However, some versions of SPSS insert
   951          // illegally truncated strings (e.g. the last character is three bytes
   952          // but the field only has room for two bytes). So to prevent the client
   953          // from receiving an invalid byte sequence, we ram everything through
   954          // our iconv machinery.
   955          iconv_t converter = iconv_open(dst_charset, src_charset);
   956          if (converter == (iconv_t)-1) {
   957              return READSTAT_ERROR_UNSUPPORTED_CHARSET;
   958          }
   959          if (ctx->converter) {
   960              iconv_close(ctx->converter);
   961          }
   962          ctx->converter = converter;
   963      }
   964      return READSTAT_OK;
   965  }
